    /\ AIMG_TOP + AFS_FLAGS <= fp /\ fp + 1 <= ff /\ as_FSB H + AFS_FLAGS <= fp /\ fp < as_FSB H + AFS_HDR
    /\ as_FSB H + AFS_HDR <= ff /\ ff + fsz k <= as_FSB H + AFS_SIZE /\ AIMG_TOP <= as_FSB H /\ as_FSB H + AFS_SIZE <= aceil
    /\ aapp (as_FSB H) AFS_SIZE.
