  (* [comment removed for export] *)
  Lemma fsobj_disjoint_sh : forall LF O n k ff fp m slo shi,
    as_RFS H LF m -> fsobj LF O n -> fresh_frame LF k ff fp ->
    0 <= O -> 0 <= n -> O + n <= AAPP_HI -> aceil <= slo ->
